// =============================================================================
// Assets — runtime loader for the game PNG assets
//
// assets/faces: one cartoon face per named roster piece (all 31 BB2025
// races, 127 unique pieces, incl. linemen), generated by the one-off
// tool /tmp/draw_faces.cpp and committed here. assets/faces.txt maps the
// exact roster position name -> file slug ("Zombie Lineman" -> zombie_lineman).
// assets/skills + assets/cards are drawn by tools/gen_assets.cpp.
//
// The loader locates the assets (compile-time FUMBBL_ASSETS_DIR >
// <exe>/../assets > CWD/assets), caches pixmaps, and falls back to a
// generic face / generic icon when something is missing.
//
// Team colors (home/away) are NOT baked into the faces: the UI draws the
// team-colored circle behind the face at runtime.
// =============================================================================
#pragma once

#include <QImage>
#include <QPixmap>
#include <QRectF>
#include <QString>

namespace assets {

// A STADIUM (round 13, user): a top-down stadium backdrop that is a
// SEPARATE, interchangeable asset from the field (the user can pick any
// stadium + any field in the future). Each stadium ships:
//   assets/stadiums/<name>/stadium.png   the top-down art (NO field in it)
//   assets/stadiums/<name>/stadium.json  a MANIFEST of normalized (0..1,
//                                         image-space) rects so the client can
//                                         align the field to the pit and the
//                                         player faces to the dugouts of ANY
//                                         stadium — the alignment is
//                                         data-driven, never hard-coded.
struct StadiumManifest {
    bool valid = false;
    QRectF fieldPit;   // the empty pit the 26x15 field is fitted into
    QRectF dugoutHome; // team 1 (home) dugout — top-left pavilion
    QRectF dugoutAway; // team 2 (away) dugout — top-right pavilion
};
// The stadium art for `name`. Null pixmap when missing.
QPixmap stadiumImage(const QString &name = QStringLiteral("medieval_arena"));
// The stadium manifest for `name` (valid=false when missing/malformed).
StadiumManifest stadiumManifest(const QString &name = QStringLiteral("medieval_arena"));

// Resolved assets directory (empty string when not found).
QString assetsDir();

// --- name -> slug maps (loaded from *_names.txt / faces.txt) ----------------
// Slug for a skill/card name (case-insensitive; "generic" when unknown).
QString skillIconSlug(const QString &skillName);
QString cardIconSlug(const QString &cardName);

// Slug for a roster POSITION NAME ("Ogre", "Zombie Lineman", "Troll Slayer"
// ...). Case-insensitive exact match against faces.txt first, then a direct
// slugification of the name, then the generic fallback.
QString faceSlug(const QString &positionName);

// --- cached pixmaps ----------------------------------------------------------
// Face for a roster position name. Unknown names (e.g. custom-named star
// pieces like "Count Luthor von Drakenborg") fall back to the RACE's
// representative face (raceHint), then to the generic human face.
// Returns a null pixmap only when the whole asset set is missing.
QPixmap playerFace(const QString &positionName, const QString &raceHint = QString());
QPixmap skillPixmap(const QString &skillName);
QPixmap cardPixmap(const QString &cardName);
// The spectacular field texture (assets/field/field.png, baked by
// tools/mockup/make_field_asset.py: crimson 1-column TD zones with vertical
// TOUCHDOWN, grid-aligned mowing stripes, no grid lines — the client draws
// those at runtime). Null pixmap when the file is missing (FieldView falls
// back to the flat fill).
QPixmap fieldTexture();
// The DUGOUT panel (assets/dugout/dugout.png): the earthy soil bench zone,
// a SEPARATE asset from the field texture — identical for every field type
// (round 12). 1:2 aspect, 3 equal bands RESERVE / KO / INJURED. Null pixmap
// when missing (FieldView falls back to a flat soil fill).
QPixmap dugoutTexture();

// Round 13 turn 4 (user: "usare i simboli ufficiali GW 2025"): the OFFICIAL
// tabletop section symbols of the dugout, rendered with Qwen-Image from the
// official GW 2025 product reference (spiked red ring + reserve arrow /
// dazed face / skull+crossbones). Transparent background; kind =
// "reserve" | "ko" | "injured". 512px sources (4K-ready: downscaled in the
// UI, never upscaled).
QPixmap dugoutSymbol(const QString &kind);

// Round 13 turn 5 (user's idea): the dugout WOOD PANEL as a separate asset
// (assets/dugout/panel.png), MOUNTED by the field view on the stadium
// manifest's dugout rects — the dugout is universal: any stadium ships its
// rect, the same (or another) panel mounts on it. Null = the vector
// fallback panel is drawn instead.
QPixmap dugoutPanel();
// The FANTASY STADIUM backdrop (assets/stadium/stands.png, Qwen top-down:
// packed medieval stands, inspired by Blood Bowl 3 — round 13, user). Fills
// the widget behind the field scene (replaces the flat grey apron). Null
// pixmap when missing (FieldView falls back to the flat stadium fill).
QPixmap stadiumTexture();

// True when the face set is available.
bool isAvailable();

// --- logo background keying (round 13, user: point 10) -----------------------
// Removes a FLAT background from a team logo. The background color is NOT
// assumed to be white — it is ESTIMATED from the image border (median of the
// edge pixels), so ANY flat background works (white, red, blue, or a logo the
// user uploaded with their own backdrop). Every pixel CONNECTED to the border
// and within a tolerance of the estimated background becomes transparent; the
// SAME color INSIDE the logo (not border-connected) is preserved (e.g. a white
// emblem on a white field stays white).
//
// Guards (return the image UNCHANGED when keying would be destructive):
//   * the image already carries a real alpha channel (transparent PNG);
//   * the border is not a uniform flat color (the logo touches the edges, or
//     the backdrop is a gradient/photo) — keying there would eat the logo.
QImage keyBackground(QImage img);

} // namespace assets
